const structuredPrompt = $input.first().json.output.final_prompt;
return {
  json: {
    prompt: JSON.stringify(structuredPrompt), // this escapes it correctly!
    model: "veo3_fast",
    aspectRatio: "16:9"
  }
};

// Merge inventory and sales data
const inventoryData = $input.first().json;
const salesData = $input.last().json;

// Create a map of sales data by product_id
const salesMap = {};
if (Array.isArray(salesData)) {
  salesData.forEach(sale => {
    salesMap[sale.product_id] = sale;
  });
} else {
  salesMap[salesData.product_id] = salesData;
}

// Merge data
const mergedData = [];
const inventory = Array.isArray(inventoryData) ? inventoryData : [inventoryData];

inventory.forEach(item => {
  const salesInfo = salesMap[item.product_id] || {
    units_sold_30days: 0,
    avg_daily_sales: 0,
    trend: 'stable'
  };

  mergedData.push({
    product_id: item.product_id,
    product_name: item.product_name,
    current_stock: item.current_stock,
    reorder_point: item.reorder_point,
    supplier_id: item.supplier_id,
    units_sold_30days: salesInfo.units_sold_30days,
    avg_daily_sales: salesInfo.avg_daily_sales,
    trend: salesInfo.trend,
    unit_cost: item.unit_cost || 0,
    lead_time_days: item.lead_time_days || 7
  });
});

return mergedData.map(item => ({ json: item }));

// Parse AI response and prepare data for filtering
const item = $input.first().json;

let aiResponse;
try {
  // Try to parse the AI response
  const content = item.message?.content || item.content || '{}';
  aiResponse = typeof content === 'string' ? JSON.parse(content) : content;
} catch (error) {
  // If parsing fails, use defaults
  aiResponse = {
    should_reorder: false,
    recommended_quantity: 0,
    days_until_stockout: 999,
    forecasted_demand_30days: 0,
    confidence_level: 'low',
    reasoning: 'Failed to parse AI response'
  };
}

// Combine original data with AI forecast
const result = {
  ...item,
  ai_forecast: aiResponse,
  should_reorder: aiResponse.should_reorder,
  recommended_quantity: aiResponse.recommended_quantity,
  days_until_stockout: aiResponse.days_until_stockout,
  forecasted_demand_30days: aiResponse.forecasted_demand_30days,
  confidence_level: aiResponse.confidence_level,
  reasoning: aiResponse.reasoning
};

return { json: result };

// Generate Purchase Order
const items = $input.all();

const purchaseOrders = items.map((item, index) => {
  const data = item.json;

  // Generate unique PO number
  const poNumber = `PO-${Date.now()}-${String(index + 1).padStart(3, '0')}`;

  // Calculate order details
  const quantity = data.recommended_quantity;
  const unitCost = data.unit_cost || 0;
  const totalCost = quantity * unitCost;

  // Create purchase order
  const purchaseOrder = {
    po_number: poNumber,
    product_id: data.product_id,
    product_name: data.product_name,
    supplier_id: data.supplier_id,
    quantity: quantity,
    unit_cost: unitCost,
    total_cost: totalCost,
    currency: 'USD',
    order_date: new Date().toISOString(),
    expected_delivery: new Date(Date.now() + (data.lead_time_days * 24 * 60 * 60 * 1000)).toISOString(),
    status: 'pending',
    created_by: 'AI_System',
    notes: data.reasoning,
    forecast_data: {
      current_stock: data.current_stock,
      days_until_stockout: data.days_until_stockout,
      forecasted_demand_30days: data.forecasted_demand_30days,
      confidence_level: data.confidence_level
    }
  };

  return { json: purchaseOrder };
});

return purchaseOrders;

const text = $input.first().json.text;
const chunkSize = 1000;

let chunks = [];
for (let i = 0; i < text.length; i += chunkSize) {
  chunks.push({
    json: { chunk: text.slice(i, i + chunkSize) }
  });
}

return chunks;

// Get all input items from Google Sheets
const items = $input.all();
const alerts = [];
const lowStockItems = [];
const expiryItems = [];

for (const item of items) {
  const data = item.json;

  // Skip header row or empty entries
  if (!data.medicine_name || data.medicine_name === 'medicine_name') {
    continue;
  }

  // Stock threshold (default 10 units if not specified)
  const threshold = data.threshold || 10;

  // Expiry warning in days (30 days before expiry)
  const expiryWarningDays = 30;

  // Check Low Stock
  if (data.stock_quantity && parseInt(data.stock_quantity) <= threshold) {
    const lowStockAlert = {
      medicine_name: data.medicine_name,
      stock_quantity: data.stock_quantity,
      threshold: threshold,
      type: "Low Stock",
      alert_message: `LOW STOCK: ${data.medicine_name} has only ${data.stock_quantity} units remaining (threshold: ${threshold})`
    };

    alerts.push(lowStockAlert);
    lowStockItems.push(`• ${data.medicine_name}: ${data.stock_quantity} units (threshold: ${threshold})`);
  }

  // Check Expiry Date
  if (data.expiry_date) {
    const today = new Date();
    const expiryDate = new Date(data.expiry_date);
    const daysLeft = Math.ceil((expiryDate - today) / (1000 * 60 * 60 * 24));

    if (daysLeft <= expiryWarningDays) {
      const expiryAlert = {
        medicine_name: data.medicine_name,
        expiry_date: data.expiry_date,
        days_left: daysLeft,
        type: daysLeft > 0 ? "Near Expiry" : "Expired",
        alert_message: daysLeft > 0
          ? `NEAR EXPIRY: ${data.medicine_name} expires in ${daysLeft} days (${data.expiry_date})`
          : `EXPIRED: ${data.medicine_name} expired ${Math.abs(daysLeft)} days ago (${data.expiry_date})`
      };

      alerts.push(expiryAlert);
      expiryItems.push(daysLeft > 0 
        ? `• ${data.medicine_name}: Expires in ${daysLeft} days (${data.expiry_date})`
        : `• ${data.medicine_name}: EXPIRED ${Math.abs(daysLeft)} days ago (${data.expiry_date})`);
    }
  }
}

// Create summary for email
const emailSummary = {
  lowStockList: lowStockItems.length > 0 ? lowStockItems.join('\n') : 'No low stock items found.',
  expiryList: expiryItems.length > 0 ? expiryItems.join('\n') : 'No items near expiry or expired.',
  totalAlerts: alerts.length,
  timestamp: new Date().toISOString()
};

// Return all alerts with email summary
if (alerts.length > 0) {
  return [{ json: emailSummary }, ...alerts.map(alert => ({ json: alert }))];
} else {
  // Return empty summary if no alerts
  return [{ json: emailSummary }];
}

// Combine all competitor data
const ahrefsData = $input.first()?.json || {};
const semrushData = $input.all().find(item => item.json?.domain) || {};
const buzzsumoData = $input.all().find(item => item.json?.results) || {};

// Process competitor intelligence
const competitorIntelligence = {
  timestamp: new Date().toISOString(),
  domain: ahrefsData.target || 'N/A',
  traffic_estimate: ahrefsData.traffic?.organic?.value || 0,
  backlinks: ahrefsData.backlinks?.total || 0,
  top_keywords: semrushData.json?.keywords?.slice(0, 10) || [],
  viral_content: buzzsumoData.json?.results?.slice(0, 5) || [],
  content_gaps: [],
  publishing_frequency: '5-7 posts/week' // This would be calculated from actual data
};

// Identify content gaps (simplified logic)
if (buzzsumoData.json?.results) {
  const competitorTopics = buzzsumoData.json.results.map(article => article.title);
  competitorIntelligence.content_gaps = [
    'Sustainable packaging solutions',
    'Circular economy in fashion',
    'Eco-friendly manufacturing processes'
  ];
}

return [{ json: competitorIntelligence }];

// Combine trends and keyword data
const trendsData = $input.all().find(item => item.json?.default) || {};
const questionsData = $input.all().find(item => item.json?.questions) || {};

// Process keyword opportunities
const keywordOpportunities = {
  timestamp: new Date().toISOString(),
  trending_keywords: [],
  long_tail_questions: [],
  search_volume_trends: [],
  seasonal_patterns: [],
  content_opportunities: []
};

// Extract trending keywords from Google Trends
if (trendsData.json?.default?.timelineData) {
  keywordOpportunities.trending_keywords = trendsData.json.default.timelineData
    .slice(0, 10)
    .map(item => ({
      keyword: item.formattedValue || 'Unknown',
      trend_velocity: item.value?.[0] || 0,
      region: 'US'
    }));
}

// Extract questions from AnswerThePublic
if (questionsData.json?.questions) {
  keywordOpportunities.long_tail_questions = questionsData.json.questions
    .slice(0, 15)
    .map(q => ({
      question: q.question || q,
      search_volume: Math.floor(Math.random() * 1000) + 100, // Placeholder
      difficulty: Math.floor(Math.random() * 100) + 1,
      suggested_format: ['blog', 'video', 'infographic'][Math.floor(Math.random() * 3)]
    }));
}

// Generate content opportunities
keywordOpportunities.content_opportunities = [
  {
    title: '5 Sustainable Fashion Trends Taking Over 2024',
    keyword_target: 'sustainable fashion trends',
    estimated_traffic: 2500,
    content_type: 'blog',
    priority: 'high'
  },
  {
    title: 'How to Build a Circular Economy Wardrobe',
    keyword_target: 'circular economy fashion',
    estimated_traffic: 1800,
    content_type: 'guide',
    priority: 'medium'
  }
];

return [{ json: keywordOpportunities }];

// Process Reddit audience insights
const redditData = $input.first()?.json || {};

const audienceInsights = {
  timestamp: new Date().toISOString(),
  top_pain_points: [],
  common_questions: [],
  sentiment_analysis: 'neutral',
  engagement_topics: [],
  regional_preferences: {}
};

// Extract pain points from Reddit posts
if (redditData.data?.children) {
  const posts = redditData.data.children;

  audienceInsights.top_pain_points = posts
    .filter(post => post.data.title.includes('problem') || post.data.title.includes('issue'))
    .slice(0, 10)
    .map(post => ({
      pain_point: post.data.title,
      upvotes: post.data.ups || 0,
      comments: post.data.num_comments || 0,
      source: 'reddit'
    }));

  audienceInsights.common_questions = posts
    .filter(post => post.data.title.includes('?') || post.data.title.toLowerCase().includes('how'))
    .slice(0, 10)
    .map(post => ({
      question: post.data.title,
      engagement_score: (post.data.ups || 0) + (post.data.num_comments || 0),
      category: 'general'
    }));

  audienceInsights.engagement_topics = posts
    .sort((a, b) => (b.data.ups || 0) - (a.data.ups || 0))
    .slice(0, 5)
    .map(post => ({
      topic: post.data.title,
      engagement_score: post.data.ups || 0,
      discussion_level: post.data.num_comments || 0
    }));
}

// Add some sample regional preferences
audienceInsights.regional_preferences = {
  'US': ['affordability', 'brand transparency'],
  'EU': ['sustainability certifications', 'local production'],
  'APAC': ['quality', 'innovation']
};

return [{ json: audienceInsights }];

